item.command:
/bin/bash -lc "python - <<'PY'
from pathlib import Path
import json,hashlib
b=Path('../../../007_LAB_Evaluation_Compare_Workflows/reference/change-baseline')
for name in ['fr-nfr-v2.md','flow-v2.md','ui-mockup-v2.html','ui-scenarios.json']:
 p=b/name
 s=p.read_text(); print(name,'lines',len(s.splitlines()),'sha256',hashlib.sha256(p.read_bytes()).hexdigest())
 if name.endswith('.md'):
  for i,l in enumerate(s.splitlines(),1):
   if l.startswith('#') or any(t in l for t in ['US-21','N=5','N = 5','ครัวเต็ม']):print(i,l)
 if name.endswith('.json'):
  j=json.loads(s); print(json.dumps(j,ensure_ascii=False,indent=2))
p=Path('../../../005_LAB_Dynamic_Workflow_Replanning/reference/step-07-plan-v3/plan-v3.json')
j=json.loads(p.read_text());print('PLAN SHA',hashlib.sha256(p.read_bytes()).hexdigest());print('PLAN KEYS',list(j))
for k,v in j.items():
 if k=='tasks':
  for t in v: print('TASK',json.dumps({a:t.get(a) for a in ['id','title','name','owner','state','status','dependencies','depends_on','inputs','outputs'] if a in t},ensure_ascii=False))
 elif k not in ['decisions','reuse','limits','artifact_dispositions']:print('FIELD',k,json.dumps(v,ensure_ascii=False)[:3500])
PY"

