function saveCapacity(){
 if(!can('manager'))return deny();
 const start=val('capacity-start'),end=val('capacity-end'),limitText=val('capacity-limit'),waitText=val('capacity-wait-minutes');
 const limit=Number(limitText),waitMinutes=Number(waitText);
 if(!/^\d{2}:\d{2}$/.test(start)||!/^\d{2}:\d{2}$/.test(end)||start>=end||!limitText||!waitText||!Number.isSafeInteger(limit)||limit<1||!Number.isSafeInteger(waitMinutes)||waitMinutes<0){
 u.capacityMessage='บันทึกไม่ได้ใน fixture: ใช้ช่วงในวันเดียว เริ่มก่อนสิ้นสุด, N จำนวนเต็มบวก และ X จำนวนเต็ม ≥ 0; ข้อจำกัดฟอร์มจำลอง ไม่ใช่ AC ร้าน';return render();
 }
 s.capacity={start,end,limit,waitMinutes};u.capacityMessage='บันทึกช่วง/N/X จำลองแล้ว · X เป็นค่าจำลอง ยังไม่ยืนยันสูตร';render();
}

